function savePageContent() {
  const pageContent = document.documentElement.outerHTML;
  const pageTitle = document.title || 'untitled';
  const filename = pageTitle.replace(/[^a-zA-Z0-9]/g, '_') + '.html'; // Sanitize filename

  const blob = new Blob([pageContent], { type: 'text/html' });
  const url = URL.createObjectURL(blob);

  chrome.downloads.download({
    url: url,
    filename: filename,
    saveAs: true // Prompts the user to choose a location
  }, (downloadId) => {
    if (chrome.runtime.lastError) {
      console.error("Download failed:", chrome.runtime.lastError.message);
      alert("Download failed: " + chrome.runtime.lastError.message); // Optional: Show error to user.
    }
    URL.revokeObjectURL(url); // Clean up the object URL. Important!
  });
}

// Optionally, add icons to an "images" folder:
// images/icon16.png, images/icon48.png, images/icon128.png
// You can use placeholder images or create your own.
```

