void handleCmdLineArgs(char *commandLine) {
  int stringLength;
  int i;
  unsigned int checkResult;
  char option;

  // Calculate the length of the command line string
  stringLength = 0;
  while (commandLine[stringLength] != '\0') {
    stringLength++;
  }

  // Process the command line arguments if the string is not empty
  if (stringLength > 0) {
    i = 0;
    while (i < stringLength) {
      // Check if the current character is part of a Shift-JIS character
      checkResult = RK_CheckSJIS((checkResult & 0xFFFFFF00) | (unsigned char)commandLine[i]);

      if (checkResult == 1) {
        // Skip the second byte of a Shift-JIS character
        i++;
      } else if (commandLine[i] == '/') {
        // Handle command line options starting with '/'
        option = commandLine[i + 1] | 0x20; // Convert to lowercase

        if (option == 'w') {
          // Set windowed mode
          IsWindowedMode = 1;
        } else if (option == 'f') {
          // Set fullscreen mode
          IsWindowedMode = 0;
        }
      }

      i++;
    }
  }
}
```

