using System;

public class PiCalculator
{
    public static void Main(string[] args)
    {
        // Calculate Pi up to 5 decimal places using the Math.PI constant.
        double pi = Math.PI;
        double piRounded = Math.Round(pi, 5);

        Console.WriteLine("Pi rounded to 5 decimal places: " + piRounded);

        // Convert the rounded value to an integer (without loss of precision in this specific case)
        int piInt = (int)(piRounded * 100000); // Multiply by 100000 to shift the decimal 5 places to the right

        // XOR the integer representation twice with a chosen key (e.g., 12345)
        int key = 12345;
        int xorResult1 = piInt ^ key;
        int xorResult2 = xorResult1 ^ key;

        Console.WriteLine("Integer representation of Pi x 100000: " + piInt);
        Console.WriteLine("XOR result after the first XOR: " + xorResult1);
        Console.WriteLine("XOR result after the second XOR: " + xorResult2);

        // Verify that XORing twice with the same key restores the original value
        if (xorResult2 == piInt)
        {
            Console.WriteLine("Double XOR successfully restored the original integer value.");
        }
        else
        {
            Console.WriteLine("Double XOR failed to restore the original integer value.");
        }

        // Optionally, convert the XORed values back to doubles if needed for further calculations
        double xorResult1Double = (double)xorResult1 / 100000;
        double xorResult2Double = (double)xorResult2 / 100000;

        Console.WriteLine("XOR result after the first XOR (converted back to double): " + xorResult1Double);
        Console.WriteLine("XOR result after the second XOR (converted back to double): " + xorResult2Double);

        Console.WriteLine("Original rounded pi value: " + piRounded);
        Console.WriteLine("XORed twice and converted back to double: " + xorResult2Double);

    }
}
```

