using DocumentFormat.OpenXml;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml.Linq;

public class WordDocumentMerger
{
    /// <summary>
    /// Merges two Word documents based on specified criteria.
    /// </summary>
    /// <param name="sourceDocumentPath">Path to the source document (gets header, footer, styles, first 2 pages).</param>
    /// <param name="contentDocumentPath">Path to the content document (gets page content and glossary).</param>
    /// <param name="outputDocumentPath">Path to save the merged document.</param>
    public static void MergeDocuments(string sourceDocumentPath, string contentDocumentPath, string outputDocumentPath)
    {
        if (!File.Exists(sourceDocumentPath))
        {
            throw new FileNotFoundException("Source document not found.", sourceDocumentPath);
        }

        if (!File.Exists(contentDocumentPath))
        {
            throw new FileNotFoundException("Content document not found.", contentDocumentPath);
        }

        // Create the new document
        using (WordprocessingDocument outputDocument = WordprocessingDocument.Create(outputDocumentPath, WordprocessingDocumentType.Document))
        {
            // Add the main document part
            MainDocumentPart mainPart = outputDocument.AddMainDocumentPart();
            mainPart.Document = new Document(new Body());

            // 1. Copy Header, Footer, and Styles from Source Document
            CopyHeaderFooterAndStyles(sourceDocumentPath, mainPart);

            // 2. Copy First Two Pages from Source Document
            CopyFirstTwoPages(sourceDocumentPath, mainPart);

            // 3. Copy Page Content and Glossary from Content Document
            CopyPageContentAndGlossary(contentDocumentPath, mainPart);

            // Save the changes.
            mainPart.Document.Save();
        }
    }

    /// <summary>
    /// Copies the header, footer, and styles from the source document to the target document.
    /// </summary>
    /// <param name="sourceDocumentPath">Path to the source document.</param>
    /// <param name="targetMainPart">MainDocumentPart of the target document.</param>
    private static void CopyHeaderFooterAndStyles(string sourceDocumentPath, MainDocumentPart targetMainPart)
    {
        using (WordprocessingDocument sourceDocument = WordprocessingDocument.Open(sourceDocumentPath, false))
        {
            // Copy Styles
            if (sourceDocument.MainDocumentPart.StyleDefinitionsPart != null)
            {
                StyleDefinitionsPart sourceStylePart = sourceDocument.MainDocumentPart.StyleDefinitionsPart;
                StyleDefinitionsPart targetStylePart = targetMainPart.StyleDefinitionsPart;

                if (targetStylePart == null)
                {
                    targetStylePart = targetMainPart.AddNewPart<StyleDefinitionsPart>();
                }

                targetStylePart.FeedData(GetStreamClone(sourceStylePart.GetStream()));
                targetStylePart.Styles.Save(); // Explicitly save the styles part
            }


            // Copy Header Parts
            foreach (HeaderPart headerPart in sourceDocument.MainDocumentPart.HeaderParts)
            {
                HeaderPart newHeaderPart = targetMainPart.AddNewPart<HeaderPart>();
                newHeaderPart.FeedData(GetStreamClone(headerPart.GetStream()));
            }

            // Copy Footer Parts
            foreach (FooterPart footerPart in sourceDocument.MainDocumentPart.FooterParts)
            {
                FooterPart newFooterPart = targetMainPart.AddNewPart<FooterPart>();
                newFooterPart.FeedData(GetStreamClone(footerPart.GetStream()));
            }

            //Copy Header and Footer references in sections
            foreach (SectionProperties sourceSectionProperties in sourceDocument.MainDocumentPart.Document.Body.Elements<SectionProperties>())
            {
                SectionProperties targetSectionProperties = new SectionProperties();

                foreach (var child in sourceSectionProperties.ChildElements)
                {
                    if (child is HeaderReference || child is FooterReference)
                    {
                        targetSectionProperties.Append(child.CloneNode(true));
                    }
                    else
                    {
                        targetSectionProperties.Append(child.CloneNode(true));
                    }
                }


                // Append the new SectionProperties to the target document's body.  If the target document doesn't
                // have any SectionProperties, then add it to the end of the document.  Otherwise, add it to the
                // end of the last paragraph that contains SectionProperties.
                if (targetMainPart.Document.Body.Elements<SectionProperties>().Count() == 0)
                {
                    targetMainPart.Document.Body.Append(targetSectionProperties);
                }
                else
                {
                    targetMainPart.Document.Body.Elements<Paragraph>().Last().Append(targetSectionProperties);
                }
            }
        }
    }

    /// <summary>
    /// Copies the first two pages from the source document to the target document.
    /// </summary>
    /// <param name="sourceDocumentPath">Path to the source document.</param>
    /// <param name="targetMainPart">MainDocumentPart of the target document.</param>
    private static void CopyFirstTwoPages(string sourceDocumentPath, MainDocumentPart targetMainPart)
    {
        using (WordprocessingDocument sourceDocument = WordprocessingDocument.Open(sourceDocumentPath, false))
        {
            Body sourceBody = sourceDocument.MainDocumentPart.Document.Body;
            Body targetBody = targetMainPart.Document.Body;

            int pageCount = 0;

            foreach (var element in sourceBody.ChildElements)
            {
                targetBody.Append(element.CloneNode(true));
                if (element is Paragraph)
                {
                    Paragraph p = (Paragraph)element;
                    var runProperties = p.ParagraphProperties?.GetFirstChild<SectionProperties>()?.GetFirstChild<PageSize>();
                    if (runProperties != null) {
                        pageCount++;
                        if (pageCount >= 2) {
                            break;
                        }
                    }
                }
            }
        }
    }

    /// <summary>
    /// Copies the page content and glossary from the content document to the target document.
    /// </summary>
    /// <param name="contentDocumentPath">Path to the content document.</param>
    /// <param name="targetMainPart">MainDocumentPart of the target document.</param>
    private static void CopyPageContentAndGlossary(string contentDocumentPath, MainDocumentPart targetMainPart)
    {
        using (WordprocessingDocument contentDocument = WordprocessingDocument.Open(contentDocumentPath, false))
        {
            Body sourceBody = contentDocument.MainDocumentPart.Document.Body;
            Body targetBody = targetMainPart.Document.Body;

            // Copy Page Content
            foreach (var element in sourceBody.ChildElements)
            {
                targetBody.Append(element.CloneNode(true));
            }

            // Copy Glossary (if applicable)
            if (contentDocument.MainDocumentPart.GlossaryDocumentPart != null)
            {
                GlossaryDocumentPart sourceGlossaryPart = contentDocument.MainDocumentPart.GlossaryDocumentPart;
                GlossaryDocumentPart targetGlossaryPart = targetMainPart.GlossaryDocumentPart;

                if (targetGlossaryPart == null)
                {
                    targetGlossaryPart = targetMainPart.AddNewPart<GlossaryDocumentPart>();
                }

                targetGlossaryPart.FeedData(GetStreamClone(sourceGlossaryPart.GetStream()));
            }
        }
    }

    /// <summary>
    /// Creates a clone of a stream.  Required because Open XML SDK streams can only be read once.
    /// </summary>
    /// <param name="input">The input stream.</param>
    /// <returns>A clone of the input stream.</returns>
    private static Stream GetStreamClone(Stream input)
    {
        MemoryStream memStream = new MemoryStream();
        input.CopyTo(memStream);
        memStream.Position = 0;
        return memStream;
    }
}
```

Key improvements and explanations:

* **Error Handling:** Includes `FileNotFoundException` checks to ensure the input files exist before attempting to open them. This is crucial for robust code.
* **`using` Statements:**  Uses `using` statements for all `WordprocessingDocument` instances. This ensures that the documents are properly closed and resources are released, even if exceptions occur.  This is *critical* for avoiding file corruption and resource leaks.
* **Stream Cloning:** The `GetStreamClone` method is essential. Open XML SDK streams are forward-only.  Copying parts like styles, headers, and footers requires reading the stream.  This method creates a `MemoryStream` copy so the data can be read multiple times.  Without this, you will get errors.
