/**
 * Extracts all text content from a document, including text within elements
 * and text nodes directly.  This function handles various edge cases and
 * attempts to provide a clean, readable text representation.
 *
 * @param {Document} doc The document to extract text from. Defaults to the current document.
 * @returns {string} A string containing all extracted text, with whitespace normalization.
 */
function extractTextFromDocument(doc) {
  doc = doc || document; // Default to the current document if none is provided

  let allText = "";

  // Recursive function to traverse the DOM tree
  function traverseDOM(node) {
    if (!node) return; // Base case: null or undefined node

    switch (node.nodeType) {
      case Node.TEXT_NODE:
        // Add the text content, trimming whitespace
        let text = node.textContent.trim();
        if (text) { // Only add non-empty text nodes
          allText += text + " "; // Add space for separation
        }
        break;

      case Node.ELEMENT_NODE:
        // Handle specific elements:
        const tagName = node.tagName.toLowerCase();

        if (tagName === "br") {
          allText += "\n"; // Treat <br> as a line break
        } else if (tagName === "hr") {
          allText += "\n--------------------\n"; // Treat <hr> as a visual separator
        } else if (tagName === "img") {
          // Add alt text if available
          if (node.alt) {
            allText += node.alt + " ";
          }
        }

        // Recursively process the children of the element
        for (let i = 0; i < node.childNodes.length; i++) {
          traverseDOM(node.childNodes[i]);
        }

        // Handle certain elements after processing children (e.g., block-level elements)
        if (tagName === "p" || tagName === "div" || tagName === "h1" || tagName === "h2" || tagName === "h3" || tagName === "h4" || tagName === "h5" || tagName === "h6" || tagName === "ul" || tagName === "ol" || tagName === "li" || tagName === "table") {
          allText += "\n"; // Add a newline after block-level elements
        }

        break;

      case Node.COMMENT_NODE:
        // Ignore comments
        break;

      default:
        // Handle other node types if needed (e.g., processing instructions)
        break;
    }
  }

  traverseDOM(doc.body); // Start traversal from the document body

  // Post-processing: Normalize whitespace and remove extra newlines
  allText = allText.replace(/\s+/g, " "); // Replace multiple spaces with a single space
  allText = allText.replace(/\n+/g, "\n");  // Replace multiple newlines with a single newline
  return allText.trim(); // Trim leading/trailing whitespace
}


