// MainActivity.kt (or wherever you're handling audio)
package com.example.reverbjni

import android.Manifest
import android.content.pm.PackageManager
import android.media.*
import android.os.Bundle
import android.util.Log
import android.widget.Button
import androidx.appcompat.app.AppCompatActivity
import androidx.core.app.ActivityCompat
import androidx.core.content.ContextCompat
import java.nio.ByteBuffer
import java.nio.ByteOrder

class MainActivity : AppCompatActivity() {

    private lateinit var recordButton: Button
    private var isRecording = false
    private var audioRecord: AudioRecord? = null
    private var audioTrack: AudioTrack? = null

    // Audio configuration
    private val sampleRate = 44100 // Standard sample rate
    private val channelConfig = AudioFormat.CHANNEL_IN_MONO // Mono input
    private val audioFormat = AudioFormat.ENCODING_PCM_16BIT // 16-bit audio
    private val audioSource = MediaRecorder.AudioSource.MIC // Use the microphone as the source

    private var bufferSizeInBytes: Int = 0

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        recordButton = findViewById(R.id.recordButton)

        // Check for microphone permission
        if (ContextCompat.checkSelfPermission(this, Manifest.permission.RECORD_AUDIO)
            != PackageManager.PERMISSION_GRANTED
        ) {
            ActivityCompat.requestPermissions(
                this,
                arrayOf(Manifest.permission.RECORD_AUDIO),
                RECORD_AUDIO_PERMISSION_CODE
            )
        }

        recordButton.setOnClickListener {
            if (!isRecording) {
                startRecording()
            } else {
                stopRecording()
            }
        }

        // Load the native library
        System.loadLibrary("reverbjni")
    }

    private fun startRecording() {
        // Calculate the minimum buffer size needed for AudioRecord
        bufferSizeInBytes = AudioRecord.getMinBufferSize(sampleRate, channelConfig, audioFormat)

        if (bufferSizeInBytes == AudioRecord.ERROR_BAD_VALUE || bufferSizeInBytes == AudioRecord.ERROR) {
            Log.e(TAG, "Error initializing AudioRecord, bad value or error.")
            return
        }

        // Initialize AudioRecord
        audioRecord = AudioRecord(
            audioSource,
            sampleRate,
            channelConfig,
            audioFormat,
            bufferSizeInBytes
        )

        if (audioRecord?.state != AudioRecord.STATE_INITIALIZED) {
            Log.e(TAG, "Failed to initialize AudioRecord")
            return
        }

        // Initialize AudioTrack
        val channelConfigOut = AudioFormat.CHANNEL_OUT_MONO // Mono output (match input)
        val streamType = AudioManager.STREAM_MUSIC
        val mode = AudioTrack.MODE_STREAM // Stream audio data

        audioTrack = AudioTrack(
            streamType,
            sampleRate,
            channelConfigOut,
            audioFormat,
            bufferSizeInBytes,
            mode
        )

        if (audioTrack?.state != AudioTrack.STATE_INITIALIZED) {
            Log.e(TAG, "Failed to initialize AudioTrack")
            audioRecord?.release()
            audioRecord = null
            return
        }


        audioRecord?.startRecording()
        audioTrack?.play()

        isRecording = true
        recordButton.text = "Stop Recording"

        // Start a thread to read from AudioRecord and write to AudioTrack with reverb
        Thread {
            val buffer = ShortArray(bufferSizeInBytes / 2) // /2 because we're using 16-bit audio
            val reverbBuffer = ShortArray(bufferSizeInBytes / 2) // Buffer for the processed output

            while (isRecording) {
                val numBytesRead = audioRecord?.read(buffer, 0, buffer.size) ?: 0
                if (numBytesRead > 0) {
                    // Apply reverb using the JNI function
                    applyReverb(buffer, reverbBuffer, numBytesRead)

                    // Write the processed audio to AudioTrack
                    audioTrack?.write(reverbBuffer, 0, numBytesRead) // Use numBytesRead here

                } else {
                    Log.e(TAG, "Error reading from AudioRecord: $numBytesRead")
                    break
                }
            }
            Log.d(TAG, "Recording thread finished")
        }.start()
    }

    private fun stopRecording() {
        isRecording = false
        recordButton.text = "Start Recording"

        audioRecord?.stop()
        audioRecord?.release()
        audioRecord = null

        audioTrack?.stop()
        audioTrack?.flush()
        audioTrack?.release()
        audioTrack = null
    }


    // JNI function declaration (defined in native-lib.cpp)
    external fun applyReverb(inputBuffer: ShortArray, outputBuffer: ShortArray, numSamples: Int)

    override fun onRequestPermissionsResult(
        requestCode: Int,
        permissions: Array<String>,
        grantResults: IntArray
    ) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults)
        if (requestCode == RECORD_AUDIO_PERMISSION_CODE) {
            if (grantResults.isNotEmpty() && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                Log.i(TAG, "Audio Recording permission granted")
            } else {
                Log.w(TAG, "Audio Recording permission denied")
                // Handle the case where the user denied permission
            }
        }
    }

    companion object {
        private const val TAG = "ReverbJNI"
        private const val RECORD_AUDIO_PERMISSION_CODE = 123
    }
}

