// cpp/native-lib.cpp
#include <jni.h>
#include <android/log.h>
#include <vector>
#include <numeric>

#define TAG "ReverbJNI"

// A very basic reverb implementation (replace with a more sophisticated one)
void applySimpleReverb(short* input, short* output, int numSamples) {
    const float decay = 0.5f; // Reverb decay factor
    const int delay = 2000; // Delay in samples (adjust for desired reverb time)

    std::vector<float> reverbBuffer(numSamples + delay, 0.0f);

    for (int i = 0; i < numSamples; ++i) {
        float inputSample = static_cast<float>(input[i]) / 32768.0f; // Normalize to -1.0 to 1.0

        // Add the direct signal
        reverbBuffer[i] += inputSample;

        // Add the delayed signal (reverb)
        reverbBuffer[i + delay] += inputSample * decay;

        // Clip and convert back to short
        float outputSample = reverbBuffer[i];
        if (outputSample > 1.0f) outputSample = 1.0f;
        if (outputSample < -1.0f) outputSample = -1.0f;

        output[i] = static_cast<short>(outputSample * 32767.0f); // Scale back to 16-bit range
    }
}


extern "C" JNIEXPORT void JNICALL
Java_com_example_reverbjni_MainActivity_applyReverb(JNIEnv *env, jobject thiz,
                                                                jshortArray input_buffer,
                                                                jshortArray output_buffer,
                                                                jint num_samples) {
    jshort *input = env->GetShortArrayElements(input_buffer, nullptr);
    jshort *output = env->GetShortArrayElements(output_buffer, nullptr);

    if (input == nullptr || output == nullptr) {
        __android_log_print(ANDROID_LOG_ERROR, TAG, "Error getting array elements");
        return;
    }

    applySimpleReverb(input, output, num_samples);


    env->ReleaseShortArrayElements(input_buffer, input, JNI_ABORT); //JNI_ABORT discards changes
    env->ReleaseShortArrayElements(output_buffer, output, 0);
}
