import android.app.PendingIntent
import android.content.Intent
import android.net.VpnService
import android.os.ParcelFileDescriptor
import android.util.Log
import kotlinx.coroutines.*
import java.io.FileInputStream
import java.io.FileOutputStream
import java.net.InetAddress
import java.net.InetSocketAddress
import java.nio.ByteBuffer
import java.nio.channels.DatagramChannel
import java.nio.channels.SocketChannel
import java.util.concurrent.BlockingQueue
import java.util.concurrent.LinkedBlockingQueue
import java.util.concurrent.atomic.AtomicBoolean

class LocalVpnService : VpnService() {

    private val TAG = "LocalVpnService"

    private var vpnInterface: ParcelFileDescriptor? = null
    private var running = AtomicBoolean(false)
    private var packetQueue: BlockingQueue<Packet> = LinkedBlockingQueue()
    private var forwardingJob: Job? = null

    // Configuration parameters (customize as needed)
    private val VPN_ADDRESS = "10.0.0.1"  // VPN client address
    private val VPN_ROUTE = "0.0.0.0"     // Default route (all traffic)
    private val DNS_SERVER = "8.8.8.8"    // Public DNS server
    private val MTU = 1500                  // Maximum Transmission Unit

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        if (running.compareAndSet(false, true)) {
            forwardingJob = CoroutineScope(Dispatchers.IO).launch {
                try {
                    setupVpn()
                    forwardPackets()
                } catch (e: Exception) {
                    Log.e(TAG, "VPN Error: ${e.message}", e)
                    stopVpn()
                }
            }
        }
        return START_STICKY
    }

    private fun setupVpn() {
        try {
            val builder = Builder()
                .setSession("MyLocalVPN") // Set a session name
                .setMtu(MTU)
                .addAddress(VPN_ADDRESS, 24) // /24 subnet
                .addRoute(VPN_ROUTE, 0)  // Default route
                .addDnsServer(DNS_SERVER)
                .establish()?.also { vpnInterface = it } ?: throw IllegalStateException("Failed to establish VPN interface")

            //  Optional: Set an intent to launch when the VPN is connected
            val pendingIntent = PendingIntent.getActivity(this, 0, Intent(this, MainActivity::class.java), PendingIntent.FLAG_IMMUTABLE)
            builder.setConfigureIntent(pendingIntent)

        } catch (e: Exception) {
            Log.e(TAG, "VPN Setup Failed: ${e.message}", e)
            throw e
        }
    }

    private suspend fun forwardPackets() {
        vpnInterface?.fileDescriptor?.let { fd ->
            val inputStream = FileInputStream(fd).channel
            val outputStream = FileOutputStream(fd).channel
            val buffer = ByteBuffer.allocate(MTU)

            while (running.get()) {
                buffer.clear()
                val bytesRead = inputStream.read(buffer)
                if (bytesRead > 0) {
                    buffer.flip()
                    val packet = Packet(buffer)
                    packetQueue.put(packet) // Add packet to the queue
                    processPacket(packet)
                } else {
                    delay(10) // Avoid busy-waiting
                }
            }
        } ?: Log.e(TAG, "VPN interface is null")
    }

    private suspend fun processPacket(packet: Packet) {
        try {
            val ipHeader = packet.ip4Header
            val destinationAddress = InetAddress.getByAddress(ipHeader.destinationAddress)
            val destinationIpString = destinationAddress.hostAddress

            // Example: Filter packets destined for 8.8.8.8
            if (destinationIpString == "8.8.8.8") {
                Log.d(TAG, "Dropping packet to 8.8.8.8")
                return // Drop the packet (don't forward)
            }

            // Forward the packet to the real destination
            forwardToDestination(packet)

        } catch (e: Exception) {
            Log.e(TAG, "Error processing packet: ${e.message}", e)
        }
    }

    private suspend fun forwardToDestination(packet: Packet) {
        val ipHeader = packet.ip4Header
        val tcpHeader = packet.tcpHeader
        val udpHeader = packet.udpHeader

        val destinationAddress = InetAddress.getByAddress(ipHeader.destinationAddress)
        val destinationPort = when {
            tcpHeader != null -> tcpHeader.destinationPort
            udpHeader != null -> udpHeader.destinationPort
            else -> 0 // Not TCP or UDP (e.g., ICMP) - Handle appropriately
        }

        try {
            if (tcpHeader != null) {
                val socketChannel = SocketChannel.open()
                socketChannel.configureBlocking(true) // Use blocking for simplicity
                socketChannel.connect(InetSocketAddress(destinationAddress, destinationPort))

                // Send the TCP payload (after TCP header)
                val payloadBuffer = packet.getPayloadData()
                socketChannel.write(payloadBuffer)

                // Read response (if any) -  Handle TCP properly (ACKs, etc.) in a real implementation
                val responseBuffer = ByteBuffer.allocate(MTU)
                socketChannel.read(responseBuffer)
                responseBuffer.flip()

                // Re-package the response and send it back through the VPN
                //  (This is a simplified example - proper TCP proxying is complex)

                socketChannel.close()

            } else if (udpHeader != null) {
                val datagramChannel = DatagramChannel.open()
                datagramChannel.configureBlocking(true)
                datagramChannel.connect(InetSocketAddress(destinationAddress, destinationPort))

                // Send the UDP payload (after UDP header)
                val payloadBuffer = packet.getPayloadData()
                datagramChannel.send(payloadBuffer, InetSocketAddress(destinationAddress, destinationPort))

                // Receive response (if any)
                val responseBuffer = ByteBuffer.allocate(MTU)
                datagramChannel.receive(responseBuffer)
                responseBuffer.flip()

                // Re-package the response and send it back through the VPN
                // (This is a simplified example -  handle UDP responses properly)

                datagramChannel.close()
            } else {
                // Handle other protocols (e.g., ICMP) -  Often you'll just drop them
                Log.w(TAG, "Unsupported protocol. Dropping packet.")
                return
            }

        } catch (e: Exception) {
            Log.e(TAG, "Error forwarding packet: ${e.message}", e)
        }
    }


    override fun onDestroy() {
        stopVpn()
        super.onDestroy()
    }

    private fun stopVpn() {
        if (running.compareAndSet(true, false)) {
            forwardingJob?.cancel()
            vpnInterface?.close()
            vpnInterface = null
            stopSelf()
        }
    }

    inner class Packet(buffer: ByteBuffer) {
        val buffer: ByteBuffer = buffer.duplicate()
        val ip4Header: IP4Header = IP4Header(buffer)
        val tcpHeader: TCPHeader?
        val udpHeader: UDPHeader?

        init {
            buffer.position(ip4Header.headerLength)
            when (ip4Header.protocol) {
                IP4Header.TCP -> {
                    tcpHeader = TCPHeader(buffer)
                    buffer.position(ip4Header.headerLength + tcpHeader.headerLength)
                }
                IP4Header.UDP -> {
                    udpHeader = UDPHeader(buffer)
                    buffer.position(ip4Header.headerLength + UDPHeader.LENGTH)
                    tcpHeader = null
                }
                else -> {
                    tcpHeader = null
                    udpHeader = null
                }
            }
        }

        fun getPayloadData(): ByteBuffer {
            return buffer.slice()
        }
    }

    // --- Header Classes ---

    class IP4Header(buffer: ByteBuffer) {
        var versionAndIHL: Byte = buffer.get()
        var tos: Byte = buffer.get()
        var totalLength: Short = buffer.short
        var id: Short = buffer.short
        var flagsAndOffset: Short = buffer.short
        var ttl: Byte = buffer.get()
        var protocol: Byte = buffer.get()
        var checksum: Short = buffer.short
        var sourceAddress: ByteArray = ByteArray(4).apply { buffer.get(this) }
        var destinationAddress: ByteArray = ByteArray(4).apply { buffer.get(this) }

        val version: Int
            get() = (versionAndIHL.toInt() ushr 4) and 0x0F

        val headerLength: Int
            get() = (versionAndIHL.toInt() and 0x0F) * 4

        companion object {
            const val TCP: Byte = 6
            const val UDP: Byte = 17
        }
    }

    class TCPHeader(buffer: ByteBuffer) {
        var sourcePort: Short = buffer.short
        var destinationPort: Short = buffer.short
        var sequenceNumber: Int = buffer.int
        var ackNumber: Int = buffer.int
        var dataOffsetAndReserved: Byte = buffer.get()
        var flags: Byte = buffer.get()
        var windowSize: Short = buffer.short
        var checksum: Short = buffer.short
        var urgentPointer: Short = buffer.short

        val headerLength: Int
            get() = (dataOffsetAndReserved.toInt() ushr 4) * 4
    }

    class UDPHeader(buffer: ByteBuffer) {
        var sourcePort: Short = buffer.short
        var destinationPort: Short = buffer.short
        var length: Short = buffer.short
        var checksum: Short = buffer.short

        companion object {
            const val LENGTH = 8
        }
    }

}
