    {
        Schema::create('favorites', function (Blueprint $table) {
            $table->id();
            $table->foreignId('user_id')->constrained()->onDelete('cascade');
            $table->string('business_name');
            $table->timestamps();

            $table->unique(['user_id', 'business_name']); // Prevent duplicate favorites for a user
        });
    }

    /**
