// --- Constants ---

const TCP_HEADER_SIZE = 20; // Minimum size, excluding options
const TCP_FLAG_SYN = 0x02;
const TCP_FLAG_ACK = 0x10;
const TCP_FLAG_FIN = 0x01;
const TCP_FLAG_RST = 0x04;
const TCP_OPTION_MSS = 2;  // Maximum Segment Size Option
const TCP_OPTION_END = 0;

// --- Types ---

interface TCPHeader {
  sourcePort: number;
  destinationPort: number;
  sequenceNumber: number;
  acknowledgmentNumber: number;
  dataOffset: number; // Number of 32-bit words in the header (header length in bytes = dataOffset * 4)
  flags: number;
  windowSize: number;
  checksum: number;
  urgentPointer: number;
  options: Uint8Array; // Raw options data
}

interface TCPPacket {
  header: TCPHeader;
  payload: Uint8Array;
}

interface TCPSocket {
  localPort: number;
  remoteAddress: string; // IPv4 address as string
  remotePort: number;
  sequenceNumber: number;
  acknowledgmentNumber: number;
  state: TCPSocketState;
  receiveBuffer: Uint8Array; // Buffer to hold received data
  sendBuffer: Uint8Array; // Buffer to hold data to be sent
  mss: number; // Maximum Segment Size
  onData: (data: Uint8Array) => void; // Callback for received data
  onClose: () => void; // Callback for connection close
  onError: (error: string) => void; // Callback for errors
  lastAckSent: number;
}

enum TCPSocketState {
  CLOSED,
  LISTEN,
  SYN_SENT,
  SYN_RECEIVED,
  ESTABLISHED,
  FIN_WAIT_1,
  FIN_WAIT_2,
  CLOSE_WAIT,
  LAST_ACK,
  TIME_WAIT,
  CLOSING,
}

// --- Utility Functions ---

function uint16(arr: Uint8Array, offset: number): number {
  return (arr[offset] << 8) | arr[offset + 1];
}

function uint32(arr: Uint8Array, offset: number): number {
  return (arr[offset] << 24) | (arr[offset + 1] << 16) | (arr[offset + 2] << 8) | arr[offset + 3];
}

function writeUint16(arr: Uint8Array, offset: number, value: number): void {
  arr[offset] = (value >> 8) & 0xFF;
  arr[offset + 1] = value & 0xFF;
}

function writeUint32(arr: Uint8Array, offset: number, value: number): void {
  arr[offset] = (value >> 24) & 0xFF;
  arr[offset + 1] = (value >> 16) & 0xFF;
  arr[offset + 2] = (value >> 8) & 0xFF;
  arr[offset + 3] = value & 0xFF;
}

function calculateTCPChecksum(header: Uint8Array, payload: Uint8Array, sourceAddress: string, destinationAddress: string): number {
  // Pseudo-header (IPv4 addresses and protocol)
  const pseudoHeader = new Uint8Array(12);
  const sourceAddressBytes = sourceAddress.split(".").map(Number);
  const destinationAddressBytes = destinationAddress.split(".").map(Number);

  writeUint32(pseudoHeader, 0, (sourceAddressBytes[0] << 24) | (sourceAddressBytes[1] << 16) | (sourceAddressBytes[2] << 8) | sourceAddressBytes[3]);
  writeUint32(pseudoHeader, 4, (destinationAddressBytes[0] << 24) | (destinationAddressBytes[1] << 16) | (destinationAddressBytes[2] << 8) | destinationAddressBytes[3]);
  pseudoHeader[8] = 0; // Reserved
  pseudoHeader[9] = 6; // Protocol (TCP = 6)
  writeUint16(pseudoHeader, 10, header.length + payload.length); // TCP Length

  // Concatenate pseudo-header, TCP header, and payload
  const data = new Uint8Array(pseudoHeader.length + header.length + payload.length);
  data.set(pseudoHeader, 0);
  data.set(header, pseudoHeader.length);
  data.set(payload, pseudoHeader.length + header.length);

  // Calculate checksum
  let sum = 0;
  for (let i = 0; i < data.length; i += 2) {
    let word16 = (data[i] << 8) & 0xFF00;
    if (i + 1 < data.length) {
      word16 |= (data[i + 1] & 0xFF);
    }
    sum += word16;
  }

  // Fold 32-bit sum to 16 bits
  while (sum >> 16) {
    sum = (sum & 0xFFFF) + (sum >> 16);
  }

  // One's complement
  return ~sum & 0xFFFF;
}

function parseTCPHeader(data: Uint8Array): TCPHeader {
  const sourcePort = uint16(data, 0);
  const destinationPort = uint16(data, 2);
  const sequenceNumber = uint32(data, 4);
  const acknowledgmentNumber = uint32(data, 8);
  const dataOffset = (data[12] >> 4) & 0x0F;
  const flags = data[13];
  const windowSize = uint16(data, 14);
  const checksum = uint16(data, 16);
  const urgentPointer = uint16(data, 18);
  const headerLength = dataOffset * 4;
  const options = data.slice(20, headerLength);

  return {
    sourcePort,
    destinationPort,
    sequenceNumber,
    acknowledgmentNumber,
    dataOffset,
    flags,
    windowSize,
    checksum,
    urgentPointer,
    options,
  };
}

function createTCPHeader(
  sourcePort: number,
  destinationPort: number,
  sequenceNumber: number,
  acknowledgmentNumber: number,
  flags: number,
  windowSize: number,
  options: Uint8Array = new Uint8Array(0)
): Uint8Array {
  const headerLength = TCP_HEADER_SIZE + options.length;
  const header = new Uint8Array(headerLength);

  writeUint16(header, 0, sourcePort);
  writeUint16(header, 2, destinationPort);
  writeUint32(header, 4, sequenceNumber);
  writeUint32(header, 8, acknowledgmentNumber);
  header[12] = ((headerLength / 4) << 4) & 0xF0;
  header[13] = flags;
  writeUint16(header, 14, windowSize);
  writeUint16(header, 16, 0); // Checksum (placeholder - calculated later)
  writeUint16(header, 18, 0); // Urgent Pointer

  if (options.length > 0) {
    header.set(options, TCP_HEADER_SIZE);
  }

  return header;
}

function parseTCPPacket(data: Uint8Array): TCPPacket {
  const header = parseTCPHeader(data);
  const headerLength = header.dataOffset * 4;
  const payload = data.slice(headerLength);

  return {
    header,
    payload,
  };
}

function createTCPSocket(
  localPort: number,
  remoteAddress: string,
  remotePort: number,
  onData: (data: Uint8Array) => void,
  onClose: () => void,
  onError: (error: string) => void
): TCPSocket {
  return {
    localPort,
    remoteAddress,
    remotePort,
    sequenceNumber: Math.floor(Math.random() * 0xFFFFFFFF), // Initial sequence number
    acknowledgmentNumber: 0,
    state: TCPSocketState.CLOSED,
    receiveBuffer: new Uint8Array(0),
    sendBuffer: new Uint8Array(0),
    mss: 1460, // Default MSS (adjust based on MTU)
    onData,
    onClose,
    onError,
    lastAckSent: 0,
  };
}


// --- TCP Implementation ---

class TCP {
  private sockets: { [key: string]: TCPSocket } = {};
  private ipLayer: { send: (destinationAddress: string, protocol: number, data: Uint8Array) => void }; //  Needs an IP layer for sending packets.

  constructor(ipLayer: { send: (destinationAddress: string, protocol: number, data: Uint8Array) => void }) {
      this.ipLayer = ipLayer;
  }

  /**
   * Creates a new TCP socket and starts listening for connections.
   *
   * @param {number} port The port to listen on.
   * @param {(data: Uint8Array) => void} onData Callback function for received data.
   * @param {() => void} onClose Callback function for connection close.
   * @param {(error: string) => void} onError Callback function for errors.
   * @returns {TCPSocket} The newly created TCP socket.
   */
  listen(
    port: number,
    onData: (data: Uint8Array) => void,
    onClose: () => void,
    onError: (error: string) => void
  ): TCPSocket {
    const socket = createTCPSocket(port, "", 0, onData, onClose, onError);
    socket.state = TCPSocketState.LISTEN;
    this.sockets[`${port}`] = socket;
    return socket;
  }

  /**
   * Connects to a remote host.
   *
   * @param {number} localPort The local port to use for the connection.
   * @param {string} remoteAddress The remote IP address.
   * @param {number} remotePort The remote port.
   * @param {(data: Uint8Array) => void} onData Callback function for received data.
   * @param {() => void} onClose Callback function for connection close.
   * @param {(error: string) => void} onError Callback function for errors.
   * @returns {TCPSocket} The newly created TCP socket.
   */
  connect(
    localPort: number,
    remoteAddress: string,
    remotePort: number,
    onData: (data: Uint8Array) => void,
    onClose: () => void,
    onError: (error: string) => void
  ): TCPSocket {
    const socket = createTCPSocket(localPort, remoteAddress, remotePort, onData, onClose, onError);
    socket.state = TCPSocketState.SYN_SENT;

    // Send SYN packet
    const options = this.createSynOptions(socket.mss);
    this.sendTCP(socket, TCP_FLAG_SYN, options);
    this.sockets[`${localPort}:${remoteAddress}:${remotePort}`] = socket; // Unique key for connected sockets.

    return socket;
  }

  /**
   * Sends data over the TCP connection.
   *
   * @param {TCPSocket} socket The TCP socket to send data on.
   * @param {Uint8Array} data The data to send.
   */
  send(socket: TCPSocket, data: Uint8Array): void {
    if (socket.state !== TCPSocketState.ESTABLISHED) {
      socket.onError("Cannot send data on a non-established connection.");
      return;
    }

    // Segment data into MSS-sized chunks
    for (let i = 0; i < data.length; i += socket.mss) {
      const chunk = data.slice(i, i + socket.mss);
      this.sendTCP(socket, TCP_FLAG_ACK, new Uint8Array(0), chunk);
    }
  }

  /**
   * Closes the TCP connection.
   *
   * @param {TCPSocket} socket The TCP socket to close.
   */
  close(socket: TCPSocket): void {
    if (socket.state === TCPSocketState.CLOSED) {
      return; // Already closed.
    }

    if (socket.state === TCPSocketState.ESTABLISHED) {
