#include <metal_stdlib>
using namespace metal;

// Define a structure to hold the Gaussian blur parameters.
struct BlurParameters {
    float sigma;       // Standard deviation of the Gaussian.  Larger values = more blur.
    int   kernelRadius; // Radius of the blur kernel (should be ~3 * sigma).
    int   width;      // Width of the input image.
    int   height;     // Height of the input image.
};

// Kernel function to perform Gaussian blur.
kernel void gaussianBlur(texture2d<half, access::read>  inputTexture  [[texture(0)]],
                         texture2d<half, access::write> outputTexture [[texture(1)]],
                         constant BlurParameters&       params        [[buffer(0)]],
                         uint2                           gid           [[thread_position_in_grid]])
{
    // Get the pixel coordinates.
    int x = gid.x;
    int y = gid.y;

    // Check if the pixel is within the image bounds.  Important for handling edges.
    if (x < 0 || x >= params.width || y < 0 || y >= params.height) {
        return; // Or write a default value, depending on your needs.  e.g., outputTexture.write(half4(0.0), gid);
    }

    // Calculate the Gaussian weights.  Pre-calculate for efficiency if this is a hotspot.
    //  However, this example calculates them per-pixel for clarity.
    half4 sum = half4(0.0);
    float weightSum = 0.0;

    // Iterate over the kernel region.
    for (int i = -params.kernelRadius; i <= params.kernelRadius; ++i) {
        for (int j = -params.kernelRadius; j <= params.kernelRadius; ++j) {
            // Calculate the offset coordinates.
            int offsetX = x + i;
            int offsetY = y + j;

            // Check if the offset coordinates are within the image bounds.
            if (offsetX >= 0 && offsetX < params.width && offsetY >= 0 && offsetY < params.height) {
                // Calculate the Gaussian weight.  1D separable blur would be much faster here.
                float distance = i * i + j * j;
                float weight = exp(-distance / (2.0 * params.sigma * params.sigma));

                // Read the pixel value from the input texture.
                half4 pixel = inputTexture.read(uint2(offsetX, offsetY));

                // Accumulate the weighted pixel value.
                sum += pixel * weight;
                weightSum += weight;
            }
        }
    }

    // Normalize the sum by dividing by the total weight.
    half4 blurredPixel = sum / weightSum;

    // Write the blurred pixel to the output texture.
    outputTexture.write(blurredPixel, gid);
}


// --- Separable Gaussian Blur (Faster, but more complex) ---
// This version implements a separable Gaussian blur, which is significantly faster than the 2D version above.
// It first blurs horizontally and then vertically.

