half calculateGaussianWeight(int x, float sigma) {
    float weight = exp(-(float)(x * x) / (2.0f * sigma * sigma));
    return half(weight); // Cast to half for consistency with the rest of the code
}

// Horizontal blur kernel
kernel void gaussianBlurHorizontal(texture2d<half, access::read>  inputTexture  [[texture(0)]],
                                 texture2d<half, access::write> outputTexture [[texture(1)]],
                                 constant BlurParameters&       params        [[buffer(0)]],
                                 uint2                           gid           [[thread_position_in_grid]])
{
    int x = gid.x;
    int y = gid.y;

    if (x < 0 || x >= params.width || y < 0 || y >= params.height) {
