}


// Vertical blur kernel
kernel void gaussianBlurVertical(texture2d<half, access::read>  inputTexture  [[texture(0)]],
                               texture2d<half, access::write> outputTexture [[texture(1)]],
                               constant BlurParameters&       params        [[buffer(0)]],
                               uint2                           gid           [[thread_position_in_grid]])
{
    int x = gid.x;
    int y = gid.y;

    if (x < 0 || x >= params.width || y < 0 || y >= params.height) {
        return;
    }

    half4 sum = half4(0.0);
    float weightSum = 0.0;

    for (int j = -params.kernelRadius; j <= params.kernelRadius; ++j) {
        int offsetY = y + j;

        if (offsetY >= 0 && offsetY < params.height) {
            half weight = calculateGaussianWeight(j, params.sigma);
            half4 pixel = inputTexture.read(uint2(x, offsetY));
            sum += pixel * weight;
            weightSum += weight;
        }
    }

    half4 blurredPixel = sum / weightSum;
    outputTexture.write(blurredPixel, gid);
}
