// Separable blur example (using intermediate texture)
func separableGaussianBlur(inputTexture: MTLTexture, outputTexture: MTLTexture, sigma: Float) {
    guard let device = MTLCreateSystemDefaultDevice() else {
        fatalError("Metal is not supported on this device")
    }

    let textureDescriptor = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: inputTexture.pixelFormat,
                                                                     width: inputTexture.width,
                                                                     height: inputTexture.height,
                                                                     mipmapped: false)
    textureDescriptor.usage = [.shaderRead, .shaderWrite]
    let intermediateTexture = device.makeTexture(descriptor: textureDescriptor)!

    let library = try! device.makeDefaultLibrary(bundle: Bundle.main)
    let horizontalKernelFunction = library.makeFunction(name: "gaussianBlurHorizontal")!
    let verticalKernelFunction = library.makeFunction(name: "gaussianBlurVertical")!

    let horizontalPipelineState = try! device.makeComputePipelineState(function: horizontalKernelFunction)
    let verticalPipelineState = try! device.makeComputePipelineState(function: verticalKernelFunction)

    let commandBuffer = device.makeCommandQueue()!.makeCommandBuffer()!

    var blurParams = BlurParameters(sigma: sigma,
                                     kernelRadius: Int32(ceil(3.0 * sigma)),
                                     width: Int32(inputTexture.width),
                                     height: Int32(inputTexture.height))

    let threadgroupSize = MTLSize(width: 16, height: 16, depth: 1)
    let threadgroupsPerGrid = MTLSize(width: (inputTexture.width + threadgroupSize.width - 1) / threadgroupSize.width,
                                      height: (inputTexture.height + threadgroupSize.height - 1) / threadgroupSize.height,
                                      depth: 1)

    // Horizontal pass
    let horizontalCommandEncoder = commandBuffer.makeComputeCommandEncoder()!
    horizontalCommandEncoder.setComputePipelineState(horizontalPipelineState)
    horizontalCommandEncoder.setTexture(inputTexture, index: 0)
    horizontalCommandEncoder.setTexture(intermediateTexture, index: 1)
    horizontalCommandEncoder.setBytes(&blurParams, length: MemoryLayout<BlurParameters>.size, index: 0)
    horizontalCommandEncoder.dispatchThreadgroups(threadgroupsPerGrid, threadsPerThreadgroup: threadgroupSize)
    horizontalCommandEncoder.endEncoding()

    // Vertical pass
    let verticalCommandEncoder = commandBuffer.makeComputeCommandEncoder()!
    verticalCommandEncoder.setComputePipelineState(verticalPipelineState)
    verticalCommandEncoder.setTexture(intermediateTexture, index: 0)
    verticalCommandEncoder.setTexture(outputTexture, index: 1)
    verticalCommandEncoder.setBytes(&blurParams, length: MemoryLayout<BlurParameters>.size, index: 0)
    verticalCommandEncoder.dispatchThreadgroups(threadgroupsPerGrid, threadsPerThreadgroup: threadgroupSize)
    verticalCommandEncoder.endEncoding()

    commandBuffer.commit()
    commandBuffer.waitUntilCompleted()
}

