            XPathExpression expression = xpath.compile(expressionString);

            // 5. Create a DOM Document from the XML string
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            factory.setNamespaceAware(true); // never forget this!
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document doc = builder.parse(new InputSource(new StringReader(xmlString)));


            // 6. Evaluate the XPath expression using parameters
            XPathContext context = new XPathContext(user, pass); // Provide the context
            Node result = (Node) expression.evaluate(doc, XPathConstants.NODE);  //Evaluate against the document

            if (result != null) {
