Okay, let's craft a basic PERN stack to-do list app. I'll provide the code for each part:

**1. PostgreSQL Database Setup:**

*   **Create a database named `todo_db`:**

    ```sql
    CREATE DATABASE todo_db;
    ```

*   **Create a `todos` table:**

    ```sql
    CREATE TABLE todos (
        todo_id SERIAL PRIMARY KEY,
        description VARCHAR(255) NOT NULL
    );
    ```

**2. Backend (Node.js with Express):**

*   **Project Setup:**

    1.  Create a project directory: `mkdir todo-backend`
    2.  Navigate into it: `cd todo-backend`
    3.  Initialize a Node.js project: `npm init -y`
    4.  Install dependencies: `npm install express cors pg`

*   **`server.js`:**

    ```javascript
    const express = require("express");
    const cors = require("cors");
    const { Pool } = require("pg"); // Import the Pool class

    const app = express();
    const port = 5000;

    // Middleware
    app.use(cors());
    app.use(express.json()); //req.body

    // PostgreSQL Connection Pool
    const pool = new Pool({
        user: "your_username",  // Replace with your PostgreSQL username
        host: "localhost",
        database: "todo_db",
        password: "your_password", // Replace with your PostgreSQL password
        port: 5432, // Default PostgreSQL port
    });

    // Routes

    // Create a todo
    app.post("/todos", async (req, res) => {
        try {
            const { description } = req.body;
            const newTodo = await pool.query(
                "INSERT INTO todos (description) VALUES($1) RETURNING *",
                [description]
            );

            res.json(newTodo.rows[0]);
        } catch (err) {
            console.error(err.message);
        }
    });

    // Get all todos
    app.get("/todos", async (req, res) => {
        try {
            const allTodos = await pool.query("SELECT * FROM todos");
            res.json(allTodos.rows);
        } catch (err) {
            console.error(err.message);
        }
    });

    // Get a todo
    app.get("/todos/:id", async (req, res) => {
        try {
            const { id } = req.params;
            const todo = await pool.query("SELECT * FROM todos WHERE todo_id = $1", [
                id,
            ]);

            res.json(todo.rows[0]);
        } catch (err) {
            console.error(err.message);
        }
    });

    // Update a todo
    app.put("/todos/:id", async (req, res) => {
        try {
            const { id } = req.params;
            const { description } = req.body;
            const updateTodo = await pool.query(
                "UPDATE todos SET description = $1 WHERE todo_id = $2 RETURNING *",
                [description, id]
            );

            res.json(updateTodo.rows[0]);
        } catch (err) {
            console.error(err.message);
        }
    });

    // Delete a todo
    app.delete("/todos/:id", async (req, res) => {
        try {
            const { id } = req.params;
            const deleteTodo = await pool.query("DELETE FROM todos WHERE todo_id = $1 RETURNING *", [
                id,
            ]);

            res.json(`Todo with id ${id} was deleted`);
        } catch (err) {
            console.error(err.message);
        }
    });

    app.listen(port, () => {
        console.log(`Server is running on port ${port}`);
    });
    ```

    **Explanation:**

    *   **Dependencies:**  `express` for the server, `cors` for handling cross-origin requests (needed for the frontend to communicate with the backend), and `pg` for PostgreSQL interaction.
    *   **Middleware:** `cors()` allows requests from your frontend (which will likely be on a different port). `express.json()` parses JSON request bodies.
    *   **PostgreSQL Connection Pool:**  The `Pool` manages a set of database connections, improving performance by reusing connections.  **Important:**  Replace `"your_username"` and `"your_password"` with your actual PostgreSQL credentials.
    *   **Routes:**
        *   `POST /todos`: Creates a new todo.
        *   `GET /todos`: Retrieves all todos.
        *   `GET /todos/:id`: Retrieves a specific todo by ID.
        *   `PUT /todos/:id`: Updates a todo.
        *   `DELETE /todos/:id`: Deletes a todo.
        *   Each route uses `pool.query()` to execute SQL queries. The results are sent back to the client as JSON.

**3. Frontend (React):**

*   **Project Setup:**

    1.  Create a React app (outside the `todo-backend` directory): `npx create-react-app todo-frontend`
    2.  Navigate into it: `cd todo-frontend`

*   **`src/App.js`:**

    ```javascript
    import React, { useState, useEffect } from 'react';
    import './App.css';

    function App() {
        const [todos, setTodos] = useState([]);
        const [description, setDescription] = useState('');

        useEffect(() => {
            getTodos();
        }, []);

        const getTodos = async () => {
            try {
                const response = await fetch('http://localhost:5000/todos');
                const jsonData = await response.json();

                setTodos(jsonData);
            } catch (err) {
                console.error(err.message);
            }
        };

        const createTodo = async (e) => {
            e.preventDefault();
            try {
                const body = { description };
                const response = await fetch('http://localhost:5000/todos', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(body),
                });

                const newTodo = await response.json();
                setTodos([...todos, newTodo]); // Optimistically update the UI
                setDescription(''); // Clear the input field

                //getTodos(); // Refresh the list - alternative to optimistic update
            } catch (err) {
                console.error(err.message);
            }
        };

        const deleteTodo = async (id) => {
            try {
                await fetch(`http://localhost:5000/todos/${id}`, {
                    method: 'DELETE',
                });

                setTodos(todos.filter((todo) => todo.todo_id !== id)); // Update UI after deletion
                //getTodos(); // Refresh the list - alternative to immediate update
            } catch (err) {
                console.error(err.message);
            }
        };

        return (
            <div className="App">
                <h1>PERN To-Do List</h1>

                <form onSubmit={createTodo}>
                    <input
                        type="text"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        placeholder="Add a todo"
                    />
                    <button>Add</button>
                </form>

                <ul>
                    {todos.map((todo) => (
                        <li key={todo.todo_id}>
                            {todo.description}
                            <button onClick={() => deleteTodo(todo.todo_id)}>Delete</button>
                        </li>
                    ))}
                </ul>
            </div>
        );
    }

    export default App;
    ```

*   **`src/App.css` (Optional - for basic styling):**

    ```css
    .App {
        text-align: center;
        padding: 20px;
    }

