#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <hls_stream.h>
#include <ap_fixed.h>

// Define data types
typedef ap_fixed<16, 8> fixed_t; // 16 bits total, 8 integer bits
typedef ap_int<8>  input_t;    // 8-bit unsigned integer for input pixels
typedef ap_int<4>  label_t;    // 4-bit unsigned integer for labels (0-9)


// Define constants
const int INPUT_SIZE    = 784; // 28x28 = 784
const int HIDDEN_SIZE   = 128;
const int OUTPUT_SIZE   = 10;

// Define HLS pragmas

// Function declaration (to be synthesized)
void mnist_classifier(
    hls::stream<input_t> &input_stream,
    hls::stream<label_t> &output_stream,
    const fixed_t weights_ih[INPUT_SIZE][HIDDEN_SIZE],
    const fixed_t biases_h[HIDDEN_SIZE],
    const fixed_t weights_ho[HIDDEN_SIZE][OUTPUT_SIZE],
    const fixed_t biases_o[OUTPUT_SIZE]
);


// Helper function: Sigmoid activation
fixed_t sigmoid(fixed_t x) {
#pragma HLS INLINE
    return 1 / (1 + exp(-x)); // Approximated sigmoid for HLS
}

// Main function (to be synthesized)
void mnist_classifier(
    hls::stream<input_t> &input_stream,
    hls::stream<label_t> &output_stream,
    const fixed_t weights_ih[INPUT_SIZE][HIDDEN_SIZE],
    const fixed_t biases_h[HIDDEN_SIZE],
    const fixed_t weights_ho[HIDDEN_SIZE][OUTPUT_SIZE],
    const fixed_t biases_o[OUTPUT_SIZE]
) {
#pragma HLS INTERFACE axis port=input_stream
#pragma HLS INTERFACE axis port=output_stream
#pragma HLS INTERFACE m_axi depth=784*128 port=weights_ih offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi depth=128 port=biases_h offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi depth=128*10 port=weights_ho offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi depth=10 port=biases_o offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=return bundle=control

    fixed_t hidden_layer_output[HIDDEN_SIZE];
    fixed_t output_layer_output[OUTPUT_SIZE];
    input_t input_pixels[INPUT_SIZE];

    // Read input image from the stream
    for (int i = 0; i < INPUT_SIZE; i++) {
#pragma HLS PIPELINE
        input_pixels[i] = input_stream.read();
    }

    // Hidden layer computation
    for (int j = 0; j < HIDDEN_SIZE; j++) {
#pragma HLS PIPELINE
        fixed_t sum = biases_h[j];
        for (int i = 0; i < INPUT_SIZE; i++) {
            sum += (fixed_t)input_pixels[i] * weights_ih[i][j];
        }
        hidden_layer_output[j] = sigmoid(sum);
    }

    // Output layer computation
    for (int k = 0; k < OUTPUT_SIZE; k++) {
#pragma HLS PIPELINE
        fixed_t sum = biases_o[k];
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            sum += hidden_layer_output[j] * weights_ho[j][k];
        }
        output_layer_output[k] = sigmoid(sum); // or ReLU, or other activation
    }

    // Determine the predicted digit (argmax)
    label_t predicted_digit = 0;
    fixed_t max_activation = output_layer_output[0];
    for (int k = 1; k < OUTPUT_SIZE; k++) {
#pragma HLS PIPELINE
        if (output_layer_output[k] > max_activation) {
            max_activation = output_layer_output[k];
            predicted_digit = k;
        }
    }

    // Write the predicted digit to the output stream
    output_stream.write(predicted_digit);
}


