```typescript
class RNN {
  private weights_ih: number[][]; // Input to hidden weights
  private weights_hh: number[][]; // Hidden to hidden weights
  private weights_ho: number[][]; // Hidden to output weights
  private bias_h: number[];      // Hidden layer bias
  private bias_o: number[];      // Output layer bias
  private hidden_size: number;
  private input_size: number;
  private output_size: number;
  private learning_rate: number;

  constructor(
    input_size: number,
    hidden_size: number,
    output_size: number,
    learning_rate: number = 0.1 // Default learning rate
  ) {
    this.input_size = input_size;
    this.hidden_size = hidden_size;
    this.output_size = output_size;
    this.learning_rate = learning_rate;

    // Initialize weights and biases with random values between -1 and 1
    this.weights_ih = this.initializeMatrix(hidden_size, input_size);
    this.weights_hh = this.initializeMatrix(hidden_size, hidden_size);
    this.weights_ho = this.initializeMatrix(output_size, hidden_size);
    this.bias_h = this.initializeArray(hidden_size);
    this.bias_o = this.initializeArray(output_size);
  }

  private initializeMatrix(rows: number, cols: number): number[][] {
    const matrix: number[][] = [];
    for (let i = 0; i < rows; i++) {
      matrix[i] = [];
      for (let j = 0; j < cols; j++) {
        matrix[i][j] = Math.random() * 2 - 1; // Random values between -1 and 1
      }
    }
    return matrix;
  }

  private initializeArray(size: number): number[] {
    const array: number[] = [];
    for (let i = 0; i < size; i++) {
      array[i] = Math.random() * 2 - 1; // Random values between -1 and 1
    }
    return array;
  }

  private sigmoid(x: number): number {
    return 1 / (1 + Math.exp(-x));
  }

  private dsigmoid(y: number): number { // Derivative of sigmoid
    return y * (1 - y);
  }

  private tanh(x: number): number {
    return Math.tanh(x);
  }

  private dtanh(y: number): number {  //Derivative of tanh
    return 1 - (y * y);
  }

  private matrixMultiply(a: number[][], b: number[][]): number[][] {
    const rowsA = a.length;
    const colsA = a[0].length;
    const rowsB = b.length;
    const colsB = b[0].length;

    if (colsA !== rowsB) {
      throw new Error("Matrices cannot be multiplied: Incompatible dimensions.");
    }

    const result: number[][] = [];
    for (let i = 0; i < rowsA; i++) {
      result[i] = [];
      for (let j = 0; j < colsB; j++) {
        let sum = 0;
        for (let k = 0; k < colsA; k++) {
          sum += a[i][k] * b[k][j];
        }
        result[i][j] = sum;
      }
    }
    return result;
  }

  private vectorMultiplyMatrix(vector: number[], matrix: number[][]): number[] {
    const rows = matrix.length;
    const cols = matrix[0].length;

    if (vector.length !== rows) {
      throw new Error("Vector and matrix dimensions are incompatible for multiplication.");
    }

    const result: number[] = [];
    for (let j = 0; j < cols; j++) {
      let sum = 0;
      for (let i = 0; i < rows; i++) {
        sum += vector[i] * matrix[i][j];
      }
      result[j] = sum;
    }
    return result;
  }

  private matrixAddVector(matrix: number[][], vector: number[]): number[][] {
    const rows = matrix.length;
    const cols = matrix[0].length;

    if (vector.length !== cols) {
      throw new Error("Matrix and vector dimensions are incompatible for addition.");
    }

    const result: number[][] = [];
    for (let i = 0; i < rows; i++) {
      result[i] = [];
      for (let j = 0; j < cols; j++) {
        result[i][j] = matrix[i][j] + vector[j];
      }
    }
    return result;
  }

  private vectorAddVector(a: number[], b: number[]): number[] {
    if (a.length !== b.length) {
      throw new Error("Vectors must have the same length for addition.");
    }

    const result: number[] = [];
    for (let i = 0; i < a.length; i++) {
      result[i] = a[i] + b[i];
    }
    return result;
  }


  private vectorToMatrix(vector: number[]): number[][] {
    return vector.map(x => [x]);
  }

  private matrixToVector(matrix: number[][]): number[] {
    return matrix.map(row => row[0]);
  }

  // Forward pass through a single time step
  public forward(input: number[], previous_hidden: number[]): { output: number[], hidden: number[] } {

    //Input to hidden
    let ih = this.vectorToMatrix(input);
    let hidden_pre = this.vectorMultiplyMatrix(input, this.weights_ih[0]);
    for(let i = 1; i < this.weights_ih.length; i++) {
      hidden_pre = this.vectorAddVector(hidden_pre, this.vectorMultiplyMatrix(input, this.weights_ih[i]));
    }
    hidden_pre = this.vectorAddVector(hidden_pre, this.bias_h);

    //Hidden to hidden
    let hh = this.vectorToMatrix(previous_hidden);
    let hidden_pre2 = this.vectorMultiplyMatrix(previous_hidden, this.weights_hh[0]);
    for(let i = 1; i < this.weights_hh.length; i++) {
      hidden_pre2 = this.vectorAddVector(hidden_pre2, this.vectorMultiplyMatrix(previous_hidden, this.weights_hh[i]));
    }

    //Apply activation function (tanh)
    let hidden_sum = this.vectorAddVector(hidden_pre, hidden_pre2);
    const hidden = hidden_sum.map(x => this.tanh(x));

    // Hidden to output
    let output_pre = this.vectorMultiplyMatrix(hidden, this.weights_ho[0]);
    for(let i = 1; i < this.weights_ho.length; i++) {
      output_pre = this.vectorAddVector(output_pre, this.vectorMultiplyMatrix(hidden, this.weights_ho[i]));
    }
    output_pre = this.vectorAddVector(output_pre, this.bias_o);

    // Apply activation function (sigmoid for output)
    const output = output_pre.map(x => this.sigmoid(x));

    return { output: output, hidden: hidden };
  }


  // Train the RNN with a sequence of inputs and targets
  public train(inputs: number[][], targets: number[][], epochs: number = 100): void {
    for (let epoch = 0; epoch < epochs; epoch++) {
      let hidden_state: number[] = this.initializeArray(this.hidden_size); // Initial hidden state

      for (let t = 0; t < inputs.length; t++) {
        const input = inputs[t];
        const target = targets[t];

        // Forward pass
        const { output, hidden } = this.forward(input, hidden_state);

        // Calculate error (for simplicity, just the difference between output and target)
        const error = output.map((o, i) => target[i] - o);

        // Backpropagation (simplified, no BPTT for multiple time steps)

        // Output layer gradients
        const d_output = output.map((o, i) => error[i] * this.dsigmoid(o));

        // Hidden layer gradients
        const d_hidden = hidden.map((h, i) => {
          let sum = 0;
          for (let j = 0; j < this.output_size; j++) {
            sum += d_output[j] * this.weights_ho[j][i];
          }
          return sum * this.dtanh(h);
        });

        // Update weights and biases

        // Hidden to Output weights
        for (let i = 0; i < this.output_size; i++) {
          for (let j = 0; j < this.hidden_size; j++) {
            this.weights_ho[i][j] += this.learning_rate * d_output[i] * hidden[j];
          }
          this.bias_o[i] += this.learning_rate * d_output[i];
        }


        // Hidden to Hidden weights
        for (let i = 0; i < this.hidden_size; i++) {
          for (let j = 0; j < this.hidden_size; j++) {
            this.weights_hh[i][j] += this.learning_rate * d_hidden[i] * hidden_state[j];
          }
          this.bias_h[i] += this.learning_rate * d_hidden[i];
        }

        // Input to Hidden weights
        for (let i = 0; i < this.hidden_size; i++) {
          for (let j = 0; j < this.input_size; j++) {
            this.weights_ih[i][j] += this.learning_rate * d_hidden[i] * input[j];
          }
        }



        // Update hidden state for the next time step
        hidden_state = hidden;
      }

      if (epoch % 10 === 0) {
          let totalError = 0;
          for (let t = 0; t < inputs.length; t++) {
            const input = inputs[t];
            const target = targets[t];

            // Forward pass
            const { output, hidden } = this.forward(input, hidden_state);
            totalError += output.reduce((acc, val, i) => acc + Math.abs(val - target[i]), 0);
          }
          console.log(`Epoch ${epoch}, Error: ${totalError / inputs.length}`);
      }
    }
  }

    // Predict the output for a sequence of inputs
  public predict(inputs: number[][]): number[][] {
      let hidden_state: number[] = this.initializeArray(this.hidden_size); // Initial hidden state
      const predictions: number[][] = [];

      for (let t = 0; t < inputs.length; t++) {
          const input = inputs[t];
          const { output, hidden } = this.forward(input, hidden_state);
          predictions.push(output);
          hidden_state = hidden; // Update hidden state for next prediction
      }

      return predictions;
  }

}


// Example Usage:
