  state: (): SelectedSessionData => ({
    userId: null,
    userName: '',
    sessionToken: '',
  }),
  actions: {
    setSessionData(data: SelectedSessionData) {
      this.userId = data.userId;
      this.userName = data.userName;
      this.sessionToken = data.sessionToken;
    },
    clearSessionData() {
      this.userId = null;
      this.userName = '';
      this.sessionToken = '';
    },
