```

```typescript
// MyComponent.vue
<script setup lang="ts">
import { useQuery } from '@tanstack/vue-query';
import { useSessionStore } from './store/sessionStore';
import { SessionResponse, SelectedSessionData } from './types/session';
import { onMounted } from 'vue';

const sessionStore = useSessionStore();

const fetchSessionData = async (): Promise<SessionResponse> => {
  const response = await fetch('/get_session');
  if (!response.ok) {
    throw new Error(`HTTP error! Status: ${response.status}`);
  }
  return await response.json();
};

const { isLoading, error, data, refetch } = useQuery<SessionResponse, Error>({
  queryKey: ['sessionData'],
  queryFn: fetchSessionData,
  onSuccess: (sessionData) => {
    const selectedData: SelectedSessionData = {
      userId: sessionData.user?.id || null,
      userName: sessionData.user?.name || '',
      sessionToken: sessionData.session?.token || '',
    };

    sessionStore.setSessionData(selectedData);
  },
});

onMounted(() => {
  refetch();
