function findEntityInJSON(jsonData, entityKey) {
  /**
   * Recursively searches a JSON object for a specific entity key.
   *
   * @param {object} jsonData - The JSON object to search.
   * @param {string} entityKey - The key to search for.
   * @param {string} path - The path to the current location in the JSON (used for tracking).
   * @returns {Array<[any, string]> | null} An array containing the value of the entity key and its path, or null if not found.  Returns an array of arrays, as the entityKey could appear multiple times.
   */

  function recurseSearch(data, key, path = "") {
    let results = [];

    if (typeof data === 'object' && data !== null) {
      if (Array.isArray(data)) {
        for (let i = 0; i < data.length; i++) {
          const indexPath = path ? `${path}[${i}]` : `[${i}]`; // Handle array indexes
          const found = recurseSearch(data[i], key, indexPath);
          if (found && found.length > 0) {
            results = results.concat(found);
          }
        }
      } else {
        for (const k in data) {
          if (data.hasOwnProperty(k)) {
            const currentPath = path ? `${path}.${k}` : k; // Handle object keys
            if (k === key) {
              results.push([data[k], currentPath]);
            }

            const found = recurseSearch(data[k], key, currentPath);

            if (found && found.length > 0) {
              results = results.concat(found);
            }
          }
        }
      }
    }

    return results.length > 0 ? results : null;
  }

  const results = recurseSearch(jsonData, entityKey);
  return results || null;
}

