use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::process::Command;
use std::path::Path;

fn main() -> io::Result<()> {
    let filename = "urls.txt"; // Replace with your file name

    let file = File::open(filename)?;
    let reader = BufReader::new(file);

    let mut youtube_urls: Vec<String> = Vec::new();
    let mut other_urls: Vec<String> = Vec::new();

    for line in reader.lines() {
        let url = line?;
        if url.contains("youtube.com") || url.contains("youtu.be") {
            youtube_urls.push(url);
        } else {
            other_urls.push(url);
        }
    }

    println!("YouTube URLs:");
    for url in &youtube_urls {
        println!("{}", url);
    }

    println!("\nOther URLs:");
    for url in &other_urls {
        println!("{}", url);
    }

    // Download YouTube URLs
    println!("\nDownloading YouTube URLs...");
    for url in &youtube_urls {
        download_youtube_url(url)?;
    }

    println!("Finished processing URLs.");
    Ok(())
}


fn download_youtube_url(url: &str) -> io::Result<()> {
    // Define the directory to save the downloaded files
    let download_dir = "downloads";

    // Create the directory if it doesn't exist
    if !Path::new(download_dir).exists() {
        std::fs::create_dir_all(download_dir)?; // Handle possible errors
    }

    let output = Command::new("yt-dlp")
        .arg(url)
        .arg("-o") // Specify output template
        .arg(format!("{}/%(title)s-%(id)s.%(ext)s", download_dir)) // Save to download directory
        .output()?;

    if output.status.success() {
        println!("Downloaded: {}", url);
    } else {
        eprintln!("Error downloading {}:", url);
        eprintln!("stdout: {}", String::from_utf8_lossy(&output.stdout));
        eprintln!("stderr: {}", String::from_utf8_lossy(&output.stderr));
    }

    Ok(())
}
```

