public class PostWithCertificate
{
    public static async Task Main(string[] args)
    {
        //  ------------ Configuration ------------
        string url = "https://your-target-url.com/api/endpoint"; // Replace with your target URL
        string certificatePath = "path/to/your/certificate.pfx"; // Replace with the path to your PFX certificate file
        string certificatePassword = "your_certificate_password"; // Replace with your certificate password (if any)
        string postData = "{\"key1\":\"value1\", \"key2\":\"value2\"}"; // Replace with your JSON or other data
        string contentType = "application/json"; // Replace with the appropriate content type (e.g., "application/json", "application/x-www-form-urlencoded")

        // ------------ Certificate Loading ------------
        X509Certificate2 certificate = null;
        try
        {
            certificate = new X509Certificate2(certificatePath, certificatePassword, X509KeyStorageFlags.MachineKeySet | X509KeyStorageFlags.PersistKeySet);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading certificate: {ex.Message}");
            return; // Exit if certificate loading fails
        }

        // ------------ Service Point Manager Configuration (Optional but often necessary) ------------
        // This is crucial for ignoring certificate validation errors if you're using a self-signed certificate or a certificate that isn't trusted.
        // **WARNING:** Disabling certificate validation can be a security risk in production environments.  Use with caution and only if you understand the implications.
        ServicePointManager.ServerCertificateValidationCallback = (sender, cert, chain, sslPolicyErrors) =>
        {
            //  This example trusts all certificates.  **NOT RECOMMENDED FOR PRODUCTION!**
            //  In a real-world scenario, you should validate the certificate against a trusted source.
            return true;

            // Example of more secure validation (replace with your actual validation logic):
            // if (cert.Subject.Contains("YourExpectedCertificateSubject"))
            // {
            //     return true;
            // }
            // else
            // {
            //     return false;
            // }
        };

        // ------------ Create and Send the Request ------------
        try
        {
            // Create the request
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
            request.Method = "POST";
            request.ContentType = contentType;
            request.ClientCertificates.Add(certificate);  // Add the client certificate
            request.PreAuthenticate = true; // Helps with NTLM authentication (if needed)
            request.UseDefaultCredentials = false; // Ensure credentials are not passed automatically

            // Convert the POST data to bytes
            byte[] data = Encoding.UTF8.GetBytes(postData);
            request.ContentLength = data.Length;


            // Write the data to the request stream (using 'using' for proper disposal)
            using (Stream requestStream = await request.GetRequestStreamAsync())
            {
                await requestStream.WriteAsync(data, 0, data.Length);
            }


            // Get the response
            using (HttpWebResponse response = (HttpWebResponse)await request.GetResponseAsync())
            using (Stream responseStream = response.GetResponseStream())
            using (StreamReader reader = new StreamReader(responseStream))
            {
                string responseText = await reader.ReadToEndAsync();

                Console.WriteLine("Response Status Code: " + response.StatusCode);
                Console.WriteLine("Response Body: " + responseText);
            }
        }
        catch (WebException ex)
        {
            Console.WriteLine($"WebException occurred: {ex.Message}");
            if (ex.Response != null)
            {
                using (HttpWebResponse errorResponse = (HttpWebResponse)ex.Response)
                {
                    Console.WriteLine("Error Status Code: " + errorResponse.StatusCode);
                    using (Stream responseStream = errorResponse.GetResponseStream())
                    using (StreamReader reader = new StreamReader(responseStream))
                    {
                        string errorText = await reader.ReadToEndAsync();
                        Console.WriteLine("Error Response Body: " + errorText);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An unexpected error occurred: {ex.Message}");
        }
        finally
        {
            // Clean up the certificate from memory (optional but recommended, especially if using MachineKeySet)
            certificate?.Reset();
        }
    }
}
