using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

public class HashtagExtractor
{
    public static List<string> ExtractHashtags(string text)
    {
        if (string.IsNullOrEmpty(text))
        {
            return new List<string>(); // Return an empty list if the input is null or empty
        }

        // Regular expression to find hashtags:
        // - '#' : Matches the hash symbol
        // - '\w+' : Matches one or more word characters (letters, numbers, and underscore)
        //   or
        // - '\p{L}+' : Matches one or more Unicode letters
        // - '\p{N}+' : Matches one or more Unicode numbers
        // - '_+' : Matches one or more underscores
        //  (This allows for hashtags with Unicode characters, numbers, and underscores)
        string pattern = @"#([\w\p{L}\p{N}_]+)";

        // Use Regex.Matches to find all matches in the text
        MatchCollection matches = Regex.Matches(text, pattern);

        // Create a list to store the extracted hashtags
        List<string> hashtags = new List<string>();

        // Iterate through the matches and extract the hashtag value (without the '#')
        foreach (Match match in matches)
        {
            hashtags.Add(match.Groups[1].Value); // Group 1 is the part inside the parentheses in the regex
        }

        return hashtags;
    }

    public static void Main(string[] args)
    {
        string text1 = "This is a sample text with #hashtags and #anotherHashtag.  Check out #123 and #你好世界.";
        string text2 = "No hashtags here.";
