        {
            std::wstring errorMsg = L"Error in pcap_findalldevs: ";
            errorMsg += std::wstring(CA2W(errbuf)); // Convert char* to wchar_t*
            WriteToLog(errorMsg);
            continue; // Go to the next iteration of the service loop
        }

        // Print the list of available devices
        for (d = alldevs; d != NULL; d = d->next)
        {
            std::wstring deviceDesc = L"Device " + std::to_wstring(++i) + L": " + CA2W(d->name);
            if (d->description) {
                deviceDesc += L" (" + CA2W(d->description) + L")";
            }
            WriteToLog(deviceDesc);
        }

        if (i == 0)
        {
            WriteToLog(L"No interfaces found! Make sure Npcap is installed.");
            pcap_freealldevs(alldevs);
            continue; // Go to the next iteration of the service loop
        }

        // Choose an interface.  For simplicity, we'll use the first one.  You'll likely want to allow configuration.
        d = alldevs;
        // Open the device
        adhandle = pcap_open_live(d->name,          // name of the device
            65536,            // portion of the packet to capture.
                              // 65536 guarantees that the whole packet will be captured on all the link layers
            1,                // promiscuous mode (1 = true)
            1000,             // read timeout
            errbuf            // error buffer
        );

        if (adhandle == NULL)
        {
            std::wstring errorMsg = L"Unable to open the adapter. ";
            errorMsg += CA2W(d->name);
            errorMsg += L" is not supported by Npcap";
            WriteToLog(errorMsg);
            pcap_freealldevs(alldevs);
            continue; // Go to the next iteration of the service loop
        }

        WriteToLog(L"Listening on " + CA2W(d->name));

        // Free the device list
        pcap_freealldevs(alldevs);

        // Start capturing packets.  We'll use a callback function to process them.
        pcap_loop(adhandle, 0, packet_handler, NULL); // 0 means capture indefinitely

        // Close the adapter
        pcap_close(adhandle);
```

**Important Notes about the Npcap Code:**

*   **Error Handling:**  The Npcap API returns error codes.  Always check these codes and handle errors gracefully.  The `errbuf` is used to store error messages; convert it to a `wstring` for logging.
*   **Device Selection:**  The code above assumes you want to capture on the *first* available network interface.  In a real application, you'll want to:
    *   Allow the user to configure which interface to use (e.g., via a configuration file or registry setting).
    *   Provide a way to list the available interfaces.
*   **Promiscuous Mode:**  Promiscuous mode (the `1` in `pcap_open_live`) allows you to capture all traffic on the network, not just traffic addressed to your machine.  You might need this for some types of network analysis.  However, be aware of the security and privacy implications.
*   **Filtering:**  You can use `pcap_compile` and `pcap_setfilter` to apply a BPF (Berkeley Packet Filter) to capture only specific types of traffic.  This can significantly reduce the amount of data you need to process.
*   **`packet_handler` Function:**  This is the function that will be called for each captured packet.  We'll define it in the next section.
*   **Memory Management:** Make sure to free any allocated memory (e.g., `pcap_freealldevs`) to avoid memory leaks.
*   **Character Set Conversion**:  You'll need to convert between `char*` (used by Npcap for device names and error messages) and `wchar_t*` (used by Windows for Unicode strings).  The code uses the `CA2W` macro from ATL (Active Template Library) for this conversion.  To use `CA2W`, you need to `#include <atlstr.h>` and `#include <atlbase.h>`.  Also, make sure your project is configured to use the Multi-Byte Character Set (Project Properties -> Configuration Properties -> General -> Character Set).  If you want to use Unicode directly, you'll need to use `pcap_findalldevs_ex` instead of `pcap_findalldevs` and handle the Unicode strings directly.

